package main

import "fmt"

// Adder is the port for the arithmetic helper. Declaring it as an interface
// creates a seam: callers that depend on Adder can receive a stub in tests
// instead of the real implementation.
type Adder interface {
	Add(a, b int) int
}

// calculator is the default Adder. It holds no state, so a zero value is ready
// to use and can be constructed directly inside a test.
type calculator struct{}

// Add implements Adder using plain integer arithmetic.
func (calculator) Add(a, b int) int {
	return a + b
}

// newAdder returns the production Adder used by the program.
func newAdder() Adder {
	return calculator{}
}

// sum applies the injected Adder to two operands. Depending only on the
// interface keeps this function easy to test with a stub implementation.
func sum(adder Adder, a, b int) int {
	return adder.Add(a, b)
}

// add is the original package helper, now a thin adapter over the calculator.
func add(a, b int) int {
	return sum(newAdder(), a, b)
}

func main() {
	fmt.Println(sum(newAdder(), 2, 3))
}

