func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

// stubAdder records the operands it receives so tests can verify wiring
// without depending on the real arithmetic.
type stubAdder struct {
	gotA   int
	gotB   int
	result int
}

func (s *stubAdder) Add(a, b int) int {
	s.gotA = a
	s.gotB = b
	return s.result
}

func TestCalculatorAdd(t *testing.T) {
	if got := (calculator{}).Add(2, 3); got != 5 {
		t.Fatalf("calculator.Add(2, 3) = %d, want 5", got)
	}
}

func TestSumUsesInjectedAdder(t *testing.T) {
	stub := &stubAdder{result: 42}
	if got := sum(stub, 7, 9); got != 42 {
		t.Fatalf("sum(stub, 7, 9) = %d, want 42", got)
	}
	if stub.gotA != 7 || stub.gotB != 9 {
		t.Fatalf("stub received (%d, %d), want (7, 9)", stub.gotA, stub.gotB)
	}
}

